// Builds src/data/strokes.ts from KanjiVG. Run by hand, the output is committed:
//   node scripts/extract-strokes.mjs
// KanjiVG is CC BY-SA 3.0 (https://kanjivg.tagaini.net), so the generated file is too.
import { writeFileSync } from 'node:fs'
import { HIRAGANA, KATAKANA } from '../src/data/kana.ts'

// pinned so a rerun gives the same file
const TAG = 'r20260714'
const BASE = `https://raw.githubusercontent.com/KanjiVG/kanjivg/${TAG}/kanji`

// monographs plus the small ya/yu/yo, a combo is drawn as its two glyphs
const SMALL = ['ゃ', 'ゅ', 'ょ', 'ャ', 'ュ', 'ョ']
const kana = [HIRAGANA, KATAKANA].flatMap(d => [...d.main, ...d.dakuten]).flatMap(c => c.kana).concat(SMALL)

async function load(k) {
  const file = k.codePointAt(0).toString(16).padStart(5, '0') + '.svg'
  const res = await fetch(`${BASE}/${file}`)
  if (!res.ok) throw new Error(`KanjiVG has no ${file} for ${k} (HTTP ${res.status})`)
  const svg = await res.text()
  const paths = [...svg.matchAll(/<path id="kvg:[^"]*-s(\d+)"[^>]*\sd="([^"]+)"/g)]
    .sort((a, b) => a[1] - b[1])
    .map(m => m[2])
  const numbers = [...svg.matchAll(/<text transform="matrix\(1 0 0 1 ([\d.]+) ([\d.]+)\)">(\d+)<\/text>/g)]
    .sort((a, b) => a[3] - b[3])
    .map(m => [Number(m[1]), Number(m[2])])
  if (paths.length === 0 || paths.length !== numbers.length)
    throw new Error(`${file}: ${paths.length} strokes but ${numbers.length} stroke numbers`)
  return [k, { paths, numbers }]
}

const entries = []
for (const k of kana) entries.push(await load(k))

const lines = entries.map(([k, s]) => `  '${k}': ${JSON.stringify(s)},`)
const out = `// Generated by scripts/extract-strokes.mjs from KanjiVG ${TAG}, do not edit by hand.
// KanjiVG (c) Ulrich Apel, CC BY-SA 3.0, https://kanjivg.tagaini.net
// This file is under the same license. viewBox is 0 0 109 109.
import type { StrokeData } from '../types'

export const STROKES: Record<string, StrokeData> = {
${lines.join('\n')}
}
`
writeFileSync(new URL('../src/data/strokes.ts', import.meta.url), out)
console.log(`wrote ${entries.length} kana`)
